#' Compute Average Daily Gain (ADG) from Growth Curves
#'
#' @description
#' Fit a growth curve to the cleaned body weights of each pig and compute
#' average daily gain (ADG) over a body weight stage.
#'
#' @param weight Result of [clean_weight()].
#' @param qc QC settings; by default the ones used by [clean_weight()].
#'   Used here: `stage_range`, `curve_model`, `max_extrap_days`,
#'   `curve_extrap`.
#' @param verbose 0 (silent), 1 (summary, default) or 2 (details).
#' @param cores Number of CPU cores for the per-pig computations. Default 1.
#'
#' @return An object of class `ppt_adg` (a list):
#'   - `per_pig`: one row per pig (pigs removed by [clean_weight()] are not
#'     included) with `stage`, `curve_used`, `curve_r2`, `adg_type`,
#'     `start_date` / `end_date` and `start_weight` / `end_weight` (when the
#'     curve reaches the stage limits, kg), `stage_days`,
#'     `extrap_days_start` / `extrap_days_end` (days the curve is
#'     extrapolated before the first / after the last weight), `adg` (g/d,
#'     slope of the daily weights over the stage), `r_squared` (of that
#'     regression), `n_observed_days`, `n_interpolated_days`,
#'     `n_curve_days` (stage days by source of the weight), `adg_curve`
#'     (g/d, stage weight difference / days of the growth curve, for
#'     comparison), `weight_status` and `weight_reason` (from
#'     [clean_weight()]);
#'   - `daily`: one row per pig and day from `start_date` to `end_date` and
#'     over the recorded days: observed `weight` (daily median, kg, `NA` on
#'     days without valid weight), `weight_filled` (observed, interpolated
#'     or curve weight, kg), `source` (`"observed"`, `"interpolated"` or
#'     `"curve"`), `predicted` weight of the growth curve with `lower` /
#'     `upper` limits (± 1.96 residual SD) and `in_stage`;
#'   - `removed`: pigs removed so far, plus pigs without ADG;
#'   - `settings`: QC settings.
#'
#' @seealso [clean_weight()] for the previous step.
#' @export
#' @examples
#' visits <- prep_visits(nedap, verbose = 0)
#' w <- clean_weight(visits, verbose = 0)
#' adg <- calc_adg(w)
#' head(adg$per_pig[, .(responder, adg_type, start_date, end_date, stage_days, adg)])
#'
#' # Gompertz curve, with quadratic fallback
#' adg_g <- calc_adg(w, qc = qc_config(curve_model = "gompertz"), verbose = 0)
#' table(adg_g$per_pig$curve_used)
#'
#' # Source of the daily weights over the stage
#' table(adg$daily[in_stage == TRUE, source])
calc_adg <- function(weight, qc = weight$settings, verbose = 1, cores = 1) {
  local_verbose(verbose)
  local_cores(cores)
  if (!inherits(weight, "ppt_weight")) {
    cli::cli_abort("{.arg weight} must be the result of {.fn clean_weight}.")
  }
  check_qc(qc)
  stage <- qc$stage_range
  ppt_msg("ADG over {stage[1]}-{stage[2]} kg ({.field {qc$curve_model}} curve)", "h1")

  kcols <- intersect(c("responder", "location", "breed", "status", "reason"), names(weight$per_pig))
  kept <- weight$per_pig[status != "removed", kcols, with = FALSE]
  data.table::setnames(kept, c("status", "reason"), c("weight_status", "weight_reason"))
  if (nrow(kept) == 0L) {
    top <- utils::head(sort(table(weight$removed$reason), decreasing = TRUE), 3L)
    cli::cli_abort(c("No pig is left after {.fn clean_weight}: all {nrow(weight$per_pig)} were removed.",
                     "i" = "Most common reasons: {paste0(names(top), ' (', top, ')', collapse = '; ')}.",
                     "i" = "See {.field $removed}, or relax {.field min_test_days} / {.field max_missing_rate} in {.fn qc_config}."))
  }
  rec <- weight$records[outlier == FALSE & responder %in% kept$responder]
  day0 <- weight$daily[, min(date - seq_days + 1L)]   # date with seq_days = 1

  fits <- fit_by_pig(rec, adg_one_pig, step = "calc_adg", qc = qc, day0 = day0)
  res <- fits$result

  daily <- if (nrow(res) > 0L) {
    data.table::rbindlist(Map(function(id, d) data.table::data.table(responder = id, d),
                              res$responder, res$daily))
  } else {
    data.table::data.table()
  }
  per_pig <- if (nrow(res) > 0L) res[, !"daily"] else data.table::data.table(responder = character())
  per_pig <- merge(kept, per_pig, by = "responder", all.x = TRUE)
  per_pig[is.na(adg_type), adg_type := "none"]
  per_pig[, stage := paste0(stage[1L], "-", stage[2L])]
  if (nrow(daily) > 0L) {
    daily <- merge(kept[, .(responder, location)], daily, by = "responder")
    data.table::setcolorder(daily, c("responder", "location", "date", "seq_days"))
    data.table::setorder(daily, location, responder, date)
  }

  cols <- c("responder", "location", "breed", "stage", "curve_used", "curve_r2",
            "adg_type", "start_date", "end_date", "start_weight", "end_weight",
            "stage_days", "extrap_days_start", "extrap_days_end", "adg", "r_squared",
            "n_observed_days", "n_interpolated_days", "n_curve_days", "adg_curve",
            "weight_status", "weight_reason")
  per_pig <- per_pig[, intersect(cols, names(per_pig)), with = FALSE]
  data.table::setorder(per_pig, location, responder)

  no_adg <- per_pig[is.na(adg)]
  why <- fits$failed$reason[match(no_adg$responder, fits$failed$responder)]
  why[is.na(why)] <- "less than 7 days of the stage covered by the curve"
  removed <- rbind(weight$removed,
                   new_removed(no_adg$responder, no_adg$location, "calc_adg", why))

  report_adg(per_pig, fits)
  new_ppt_result(per_pig = per_pig, daily = daily, removed = removed,
                 settings = qc, class = "ppt_adg")
}

# ADG for one pig. `d` holds its valid weight records. `fill = "curve"`
# fills every missing day from the growth curve (used by
# validate_weight_fill() to compare with the linear interpolation).
adg_one_pig <- function(d, qc, day0, fill = "linear") {
  first_day <- min(d$date)
  t <- as.numeric(difftime(d$entry_time, as.POSIXct(first_day, tz = "UTC"),
                           units = "days"))
  y <- d$weight
  curve <- fit_growth_curve(t, y, qc$curve_model, qc$curve_extrap %||% "curve")

  lo <- qc$stage_range[1L]
  hi <- qc$stage_range[2L]
  tmin <- min(t)
  tmax <- max(t)
  from <- tmin - qc$max_extrap_days
  to <- tmax + qc$max_extrap_days

  # end: first time the curve reaches `hi`; start: last time it rises
  # through `lo` before that end
  t_hi <- first_cross(curve$pred, hi, from, to)
  t_lo <- last_up_cross(curve$pred, lo, from, if (is.na(t_hi)) to else t_hi)
  a <- if (is.na(t_lo)) tmin else t_lo
  b <- if (is.na(t_hi)) tmax else t_hi
  tol <- 0.5
  # a pig whose curve is above the stage at the start of [a, b] or below it
  # at the end never was inside the stage
  none <- b - a < 7 || curve$pred(a) >= hi || curve$pred(b) <= lo
  adg_type <- if (none) {
    "none"
  } else if (is.na(t_lo) || is.na(t_hi)) {
    "partial"
  } else if (t_lo >= tmin - tol && t_hi <= tmax + tol) {
    "observed"
  } else {
    "extrapolated"
  }
  adg_curve <- if (none) NA_real_ else (curve$pred(b) - curve$pred(a)) * 1000 / (b - a)

  # Daily weights over the stage and the recorded days: observed (daily
  # median), linear interpolation between recorded days, growth curve before
  # the first and after the last recorded day.
  obs <- d[, .(weight = stats::median(weight)), by = date]
  obs_idx <- as.integer(obs$date - first_day)
  stage_idx <- if (none) integer() else seq(floor(a), ceiling(b) - 1)
  idx <- sort(unique(c(stage_idx, obs_idx)))
  dates <- first_day + idx
  pred <- curve$pred(idx + 0.5)
  w_obs <- obs$weight[match(idx, obs_idx)]
  miss <- is.na(w_obs)
  interp <- miss & idx > min(obs_idx) & idx < max(obs_idx) & fill == "linear"
  filled <- w_obs
  if (any(interp)) filled[interp] <- stats::approx(obs_idx, obs$weight, xout = idx[interp])$y
  filled[miss & !interp] <- pred[miss & !interp]
  daily <- data.table::data.table(
    date = dates,
    seq_days = as.integer(dates - day0) + 1L,
    weight = w_obs,
    weight_filled = filled,
    source = data.table::fcase(!miss, "observed", interp, "interpolated", default = "curve"),
    predicted = pred,
    lower = pred - 1.96 * curve$sigma,
    upper = pred + 1.96 * curve$sigma,
    in_stage = !none & (idx + 1) > a & idx < b
  )

  # ADG: slope of the daily weights over the stage days
  st <- daily[in_stage == TRUE]
  adg <- r_squared <- NA_real_
  if (nrow(st) >= 7L) {
    x <- as.numeric(st$date)
    lfit <- stats::lm(st$weight_filled ~ x)
    adg <- unname(stats::coef(lfit)[2L]) * 1000
    r_squared <- summary(lfit)$r.squared
  } else {
    adg_type <- "none"
  }

  data.table::data.table(
    curve_used = curve$name,
    curve_r2 = curve$r2,
    adg_type = adg_type,
    start_date = if (is.na(t_lo)) as.Date(NA) else first_day + floor(t_lo),
    end_date = if (is.na(t_hi)) as.Date(NA) else first_day + floor(t_hi),
    start_weight = if (none) NA_real_ else curve$pred(a),
    end_weight = if (none) NA_real_ else curve$pred(b),
    stage_days = if (none) NA_real_ else b - a,
    extrap_days_start = if (none) NA_real_ else max(0, tmin - a),
    extrap_days_end = if (none) NA_real_ else max(0, b - tmax),
    adg = adg,
    r_squared = r_squared,
    n_observed_days = sum(st$source == "observed"),
    n_interpolated_days = sum(st$source == "interpolated"),
    n_curve_days = sum(st$source == "curve"),
    adg_curve = adg_curve,
    daily = list(daily)
  )
}

# Fit a growth curve. Returns a prediction function, the fitted values,
# the residual SD, R2 and the name of the model actually used. With
# extrap = "tangent", the prediction beyond the records is a straight line;
# with extrap = "start", only before the first record.
fit_growth_curve <- function(t, y, model, extrap = "curve") {
  fit_poly <- function(k, name = paste0("poly", k)) {
    f <- stats::lm(y ~ poly(t, k, raw = TRUE))
    b <- stats::coef(f)
    b[is.na(b)] <- 0                     # aliased terms, as predict() drops them
    # evaluate the polynomial directly: much faster than predict.lm()
    list(pred = function(x) as.numeric(outer(x, 0:k, `^`) %*% b),
         fitted = stats::fitted(f), name = name)
  }
  curve <- switch(model,
    poly1 = fit_poly(1),
    poly2 = fit_poly(2),
    poly3 = fit_poly(3),
    gompertz = {
      f <- tryCatch(stats::nls(y ~ stats::SSgompertz(t, Asym, b2, b3)),
                    error = function(e) NULL)
      if (is.null(f)) {
        fit_poly(2, "poly2 (gompertz failed)")
      } else {
        list(pred = function(x) as.numeric(stats::predict(f, newdata = data.frame(t = x))),
             fitted = as.numeric(stats::fitted(f)), name = "gompertz")
      }
    }
  )
  res <- y - curve$fitted
  curve$sigma <- stats::sd(res)
  curve$r2 <- 1 - sum(res^2) / sum((y - mean(y))^2)
  if (extrap %in% c("tangent", "start")) {
    curve <- tangent_ends(curve, t, y, ends = if (extrap == "start") "start" else "both")
  }
  curve
}

# Continue the curve beyond the records by straight lines: from the curve at
# the first / last record, with the robust slope of the records of the first
# / last `window` days, limited to `slope_range` kg/d.
tangent_ends <- function(curve, t, y, ends = c("both", "start"), window = 14,
                         slope_range = c(0.2, 1.5)) {
  ends <- match.arg(ends)
  tmin <- min(t)
  tmax <- max(t)
  win <- min(window, (tmax - tmin) / 2)
  slope <- function(sel) {
    if (sum(sel) < 5L || diff(range(t[sel])) < 2) return(NA_real_)
    g <- tryCatch(stats::coef(MASS::rlm(cbind(1, t[sel]), y[sel], psi = MASS::psi.bisquare,
                                        maxit = 50))[2L],
                  error = function(e) stats::coef(stats::lm(y[sel] ~ t[sel]))[2L])
    min(slope_range[2L], max(slope_range[1L], unname(g)))
  }
  g_start <- slope(t <= tmin + win)
  g_end <- if (ends == "both") slope(t >= tmax - win) else NA_real_
  p <- curve$pred
  p_start <- p(tmin)
  p_end <- p(tmax)
  curve$pred <- function(x) {
    out <- p(x)
    lo <- x < tmin & !is.na(g_start)
    hi <- x > tmax & !is.na(g_end)
    out[lo] <- p_start + g_start * (x[lo] - tmin)
    out[hi] <- p_end + g_end * (x[hi] - tmax)
    out
  }
  curve$name <- paste0(curve$name, if (ends == "both") " + tangent" else " + tangent (start)")
  curve$tangent_slopes <- c(start = g_start, end = g_end)
  curve
}

# Last time in [from, to] at which the curve rises through `target`, NA if it
# never does (e.g. it is above `target` the whole time).
last_up_cross <- function(pred, target, from, to, step = 0.1) {
  if (to - from < step) return(NA_real_)
  g <- seq(from, to, by = step)
  p <- pred(g)
  up <- which(p[-length(p)] < target & p[-1L] >= target)
  if (length(up) == 0L) return(NA_real_)
  i <- max(up)
  g[i] + (target - p[i]) / (p[i + 1L] - p[i]) * step
}

# First time the curve rises through `target` (an extrapolated curve that
# starts above it, e.g. the left branch of a parabola, is not a crossing).
first_cross <- function(pred, target, from, to, step = 0.1) {
  if (to - from < step) return(NA_real_)
  g <- seq(from, to, by = step)
  p <- pred(g)
  up <- which(p[-length(p)] < target & p[-1L] >= target)
  if (length(up) == 0L) return(NA_real_)
  i <- up[1L]
  g[i] + (target - p[i]) / (p[i + 1L] - p[i]) * step
}

report_adg <- function(per_pig, fits) {
  types <- table(factor(per_pig$adg_type,
                        levels = c("observed", "extrapolated", "partial", "none")))
  ppt_bullets_counts(c(
    "Observed (stage inside the records)" = types[["observed"]],
    "Extrapolated" = types[["extrapolated"]],
    "Partial (stage not fully reached)" = types[["partial"]],
    "No ADG" = types[["none"]]
  ))
  fallback <- per_pig[grepl("failed", curve_used), .N]
  if (fallback > 0L) {
    ppt_msg("Gompertz did not converge for {fallback} pig{?s}: quadratic curve used", "warning")
  }
  if (types[["partial"]] > 0L) {
    ppt_warn("{types[['partial']]} pig{?s} {?does/do} not reach the whole stage: ADG is based on part of it (adg_type = \"partial\").")
  }
  if (any(!is.na(per_pig$adg))) {
    ppt_msg("Mean ADG: {round(mean(per_pig$adg, na.rm = TRUE))} g/d (SD {round(stats::sd(per_pig$adg, na.rm = TRUE))})", "success")
  }
  for (i in which(per_pig$adg_type != "observed")) {
    ppt_msg("{.val {per_pig$responder[i]}}: {per_pig$adg_type[i]}, ADG {round(per_pig$adg[i])} g/d", "info", level = 2L)
  }
  invisible(NULL)
}
